#pragma once
#include <array>
#include <cstdint>
namespace ks {
class StateProgramTask final {
public:enum class Kind {ReadIndex,WriteIndex,PartSlot};enum class Stage {RetainBank,RetainExtra,ReadBank,PreviousBank,ClearExtra,CompareBank,AdmitBank,CopyExtra,BiasExtra,ClampBank,SetBankSize,MultiplyBank,SetExtraSize,MultiplyExtra,ReadProgram,NormalizeProgram,AddBank,AddExtra,RestoreExtra,RestoreBank,ReturnIndex,ClearBias,SetDivisor,CompareIndex,AdmitIndex,SetBias,SetLargeDivisor,SubtractLargeBase,DivideIndex,WriteProgram,AddBias,IncrementBank,WriteBank,RebindMode,ReturnProgram,ClearSlot,ReadPart,DoublePart,AddSlotBase,ReturnSlot,AwaitMode,Complete};enum class Read {Bank,Program,Part};enum class Write {Bank,Program};
 StateProgramTask(Kind k,uint16_t index=0):phase_(k==Kind::ReadIndex?Stage::RetainBank:k==Kind::WriteIndex?Stage::ClearBias:Stage::ClearSlot),index_(index){}
 Stage stage()const{return phase_;}bool complete()const{return phase_==Stage::Complete;}bool awaitingMode()const{return phase_==Stage::AwaitMode;}bool resumeMode(){if(!awaitingMode())return false;phase_=Stage::ReturnProgram;return true;}uint16_t index()const{return index_;}uint8_t bank()const{return bank_;}uint8_t program()const{return program_;}uint32_t slotAddress()const{return 0x167ae +uint8_t(part_*2);}
 unsigned nextClocks(unsigned storeClocks=3)const{constexpr std::array<unsigned,40> costs{{11,11,8,3,3,3,3,3,3,3,3,15,3,15,6,3,3,3,11,11,17,3,3,6,3,3,3,6,15,12,3,3,12,20,17,3,12,3,9,17}};return unsigned(phase_)>=costs.size()?0:phase_==Stage::WriteProgram||phase_==Stage::WriteBank?costs[unsigned(phase_)]-3+storeClocks:costs[unsigned(phase_)];}
 template<class Reader,class Writer>unsigned advanceBefore(unsigned available,Reader&& read,Writer&& write,unsigned storeClocks=3){unsigned used=0;while(const auto cost=nextClocks(storeClocks)){if(cost>available-used)break;switch(phase_){case Stage::ReadBank:bank_=uint8_t(read(Read::Bank));next();break;case Stage::PreviousBank:--bank_;next();break;case Stage::ClearExtra:extra_=0;next();break;case Stage::AdmitBank:phase_=bank_<=4?Stage::SetBankSize:Stage::CopyExtra;break;case Stage::CopyExtra:extra_=bank_;next();break;case Stage::BiasExtra:extra_=uint8_t(extra_-4);next();break;case Stage::ClampBank:bank_=4;next();break;case Stage::MultiplyBank:bankBase_=unsigned(bank_)*100;next();break;case Stage::MultiplyExtra:extraBase_=unsigned(extra_)*50;next();break;
 case Stage::ReadProgram:program_=uint8_t(read(Read::Program));next();break;case Stage::NormalizeProgram:index_=program_;next();break;case Stage::AddBank:index_=uint16_t(index_+bankBase_);next();break;case Stage::AddExtra:index_=uint16_t(index_+extraBase_);next();break;
 case Stage::ClearBias:bias_=0;next();break;case Stage::SetDivisor:divisor_=100;next();break;case Stage::AdmitIndex:phase_=index_<450?Stage::DivideIndex:Stage::SetBias;break;case Stage::SetBias:bias_=4;next();break;case Stage::SetLargeDivisor:divisor_=50;next();break;case Stage::SubtractLargeBase:index_=uint16_t(index_-400);next();break;case Stage::DivideIndex:program_=uint8_t(index_%divisor_);bank_=uint8_t(index_/divisor_);next();break;case Stage::WriteProgram:write(Write::Program,program_);next();break;case Stage::AddBias:bank_=uint8_t(bank_+bias_);next();break;case Stage::IncrementBank:++bank_;next();break;case Stage::WriteBank:write(Write::Bank,bank_);next();break;case Stage::RebindMode:phase_=Stage::AwaitMode;break;
 case Stage::ReadPart:part_=uint8_t(read(Read::Part));next();break;case Stage::ReturnIndex:case Stage::ReturnProgram:case Stage::ReturnSlot:phase_=Stage::Complete;break;default:next();break;}used+=cost;}return used;}
private:void next(){phase_=Stage(unsigned(phase_)+1);}Stage phase_;uint16_t index_=0,bankBase_=0,extraBase_=0;uint8_t bank_=0,program_=0,extra_=0,bias_=0,divisor_=1,part_=0;
};}
